  if (action === 'login') return { ...fail('当前使用浏览器软电话，请由该坐席登录自己的账号，在“外呼坐席”点击登录。'), supported: false };
  if (!managementMethods[action]) return fail('不支持此坐席管理操作');
  const permitted = { pause: ['空闲'], unpause: ['置忙'], logout: ['空闲', '置忙'] }[action];
